
.testimonials {
  background: var(--bg);
}

.testimonials-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: clamp(44px, 6vw, 68px);
}

.testimonials-rating {
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: flex-end;
  flex: none;
}

.testimonials-stars {
  color: var(--gold);
  font-size: 20px;
  letter-spacing: 3px;
}

.testimonials-rating-text {
  font-size: 13px;
  color: var(--text-muted);
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.testimonial-card {
  display: flex;
  flex-direction: column;
  padding: 32px 30px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background:
    radial-gradient(120% 90% at 0% 0%, rgba(201, 169, 98, 0.06) 0%, transparent 55%),
    var(--surface);
  transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.35s ease;
}

.testimonial-card:hover {
  transform: translateY(-5px);
  border-color: var(--border-gold);
}

.testimonial-quote-icon {
  color: var(--gold);
  opacity: 0.85;
  margin-bottom: 18px;
}

.testimonial-quote {
  font-family: var(--font-display);
  font-size: 18.5px;
  font-style: italic;
  line-height: 1.5;
  flex: 1;
}

.testimonial-footer {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 26px;
  padding-top: 22px;
  border-top: 1px solid var(--border);
}

.testimonial-avatar {
  flex: none;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-size: 17px;
  color: #181307;
  background: linear-gradient(135deg, var(--gold-soft), var(--gold));
}

.testimonial-author {
  font-size: 14px;
  font-weight: 600;
}

.testimonial-car {
  font-size: 12.5px;
  color: var(--text-muted);
}

@media (max-width: 900px) {
  .testimonials-head {
    flex-direction: column;
    align-items: flex-start;
    gap: 18px;
  }

  .testimonials-rating {
    align-items: flex-start;
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
  }
}
